INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65515825', 65515825, 'analyze_legacy', 'Provinsi Kalimantan Tengah', 'provinsi', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'Pendampingan Pembangunan Perumahan, Permukiman, Air Minum dan Sanitasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Tengah, Palangka Raya (Kota)', 560000000, 'January 2026', 'APBD', 1, 1, '7 paket', 'TENAGA PENDAMPINGAN PEMBINAAN DAN EVALUASI KINERJA INFRASTRUKTUR AIR MINUM 1; TENAGA PENDAMPINGAN PEMBINAAN DAN EVALUASI KINERJA INFRASTRUKTUR AIR MINUM 2; TENAGA PENDAMPINGAN IMPLEMENTASI DOKUMEN SSK 1; TENAGA PENDAMPINGAN IMPLEMENTASI DOKUMEN SSK 2; TENAGA PENDAMPINGAN IMPLEMENTASI DOKUMEN SSK 3; TENAGA PENDAMPINGAN IMPLEMENTASI DOKUMEN SSK 4; TENAGA PENDAMPINGAN PEMUTAKHIRAN DOKUMEN SSK 1;', '1) Mendukung pelaksanaan kegiatan di Bidang Cipta Karya, khususnya pendampingan Pendampingan Pembangunan Perumahan, Permukiman, Air Minum dan Sanitasi. 2) Mendukung semua pelaksanaan kegiatan koordinasi, sinkronisasi, monitoring dan evaluasi terkait pendampingan Pendampingan Pembangunan Perumahan, Permukiman, Air Minum dan Sanitasi dengan uraian tugas sebagai berikut: a) Membantu pengumpulan dan penyiapan bahan-bahan kerja/data- data/informasi; b) Membantu menganalisis dan menelaah bahan-bahan kerja/data- data/informasi; c) Membantu penyiapan dan menghadiri kegiatan Rapat/Focus Group Discussion/Seminar/Workshop; d) Membuat dan membantu penyusunan laporan pelaksanaan kegiatan; e) Melaksanakan tugas kedinasan lain yang diperintahkan oleh pimpinan baik secara tertulis maupun lisan. 3) Mendukung pelaksanaan kegiatan dan membantu melakukan tugas pengadministrasian umum terkait Sanitasi Bidang Cipta Karya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2174706);
