INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65481184', 65481184, 'analyze_legacy', 'Badan Pengusahaan Kawasan Perdagangan Bebas Dan Pelabuhan Bebas Batam', 'central', 'Badan Pengusahaan Kawasan Perdagangan Bebas dan Pelabuhan Bebas Batam', 'Pembangunan Workshop Jalan dan Jembatan', 'Pekerjaan Konstruksi', 'Tender', 'Kepulauan Riau, Batam (Kota)', 7958805000, 'February 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Paket ini meliputi pelaksanaan fisik Pembangunan Workshop Jalan dan Jembatan yang terdiri dari beberapa lingkup utama, dimulai dari pekerjaan persiapan, perizinan, dan penerapan Sistem Manajemen Keselamatan Konstruksi (SMKK). Lingkup konstruksi mencakup pembangunan gedung Workshop dengan struktur baja berat, gedung kantor permanen 2 lantai, serta bangunan gudang arsip 1 lantai. Selain bangunan gedung, pekerjaan ini juga mencakup penataan infrastruktur kawasan berupa pematangan lahan (cut and fill), pembangunan jalan beton (rigid pavement), sistem drainase (u-ditch & box culvert), pagar kawasan, serta instalasi PJU tenaga surya. Seluruh rangkaian pekerjaan mencakup instalasi Mekanikal, Elektrikal, dan Plumbing (MEP) yang terintegrasi untuk mendukung fungsi operasional fasilitas tersebut.', 'Ketentuan teknis mengenai material, peralatan, personel, dan metode kerja dilaksanakan secara komprehensif berdasarkan Dokumen Pengadaan yang menjadi satu kesatuan tidak terpisahkan, meliputi Kerangka Acuan Kerja (KAK), Gambar Rencana (DED), Spesifikasi Teknis (RKS), Daftar Kuantitas dan Harga (BoQ/HPS), serta segala bentuk perubahan atau adendum yang disepakati selama masa pelaksanaan pekerjaan. Seluruh material dan hasil pekerjaan harus memenuhi standar mutu (SNI) yang dipersyaratkan serta mengutamakan penggunaan Produk Dalam Negeri (PDN) yang memiliki sertifikat TKDN. Jangka waktu pelaksanaan pekerjaan ditetapkan selama 8 (delapan) bulan kalender dengan skema kontrak harga satuan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2177907);
