INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65522152', 65522152, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Belanja Pemeliharaan Peralatan dan Mesin Lainnya Pemeliharaan Aplikasi DJKI berupa Pemeliharaan Aplikasi Berbasis AI, Pangkalan Data Kekayaan Intelektual, Dan Dashboard Monitoring pada Direktorat Jenderal Kekayaan Intelektual TA 2026', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 540000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Melaksanakan Pemeliharaan Aplikasi Penelusuran Berbasis AI, Pangkalan Data Kekayaan Intelektual (PDKI), dan Dashboard Monitoring untuk menjamin keberfungsian dan kemudahan dalam mengoperasikan aplikasi sehingga produktivitas dapat mengimbangi pertumbuhan permohonan, peningkatan mutu kualitas sistem dengan menyempurnaakan dan memperbaiki gangguan kecil (bug) pada aplikasi.', 'Melakukan Pemeliharaan Secara Preventif yang dilakukan untuk mencegah terjadinya kerusakan pada aplikasi baik secara periodik maupun secara insidental, melakukan pemeliharaan secara korektif yang dilakukan dengan cara mengidentifikasi penyebab kerusakan dan kemudian memperbaikinya sehingga aplikasi dapat berfungsi dan beroperasi normal kembali, melaksanakan bug-fixed dan/atau update patch terhadap fitur-fitur yang ada, melaksanakan update model visual transformer pada penelusuran berbasis AI dan PDKI, melakukan pengujian fungsi sub-sub modul aplikasi atau error-bug testing oleh penyedia didampingi pengguna, rapat koordinasi setiap satu bulan sekali kepada user, laporaan pelaksanaan hasil pekerjaan dan penyerahan source code aplikasi serta manual book kepada DJKI, ketersediaan layanan dukungan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2179929);
